    ///   - samples: Mono, 16 kHz, 32-bit float PCM samples.
    ///   - context: Metadata that guides engine behaviour for this chunk.
    /// - Returns: A ``TranscriptionSegment`` representing the recognised speech.
    /// - Throws: A domain error if transcription fails or the engine is not ready.
    func transcribe(
        samples: [Float],
        context: TranscriptionContext
    ) async throws -> TranscriptionSegment

    /// Transcribes a buffer of PCM audio samples and returns every recognised
    /// segment individually rather than collapsing them into one.
    ///
    /// The default implementation delegates to ``transcribe(samples:context:)``
    /// and wraps the result in a single-element array, preserving backward
    /// compatibility for engines that produce one segment per call.
    ///
    /// Override this method when the underlying engine produces time-aligned
    /// sub-segments (e.g. WhisperKit chunks) and the caller needs fine-grained
    /// timing for downstream diarization merging.
    func transcribeSegments(
        samples: [Float],
        context: TranscriptionContext
    ) async throws -> [TranscriptionSegment]

    // MARK: - Status

    /// Returns `true` when the engine has a loaded model and is ready to accept
    /// calls to ``transcribe(samples:context:)``.
    func isReady() async -> Bool

    /// Returns the compute unit the engine used for its most recent inference.
    /// Engines that do not distinguish compute units should return `.unknown`.
    func getComputeUnit() async -> ComputeUnit

    /// Performs any warm-up work (e.g. a dummy inference pass) so that the
    /// first real call to ``transcribe(samples:context:)`` is not penalised by
    /// first-use latency.
    ///
    /// - Throws: A domain error if warm-up fails (e.g. model not loaded).
    func warmUp() async throws

    // MARK: - Unload

    /// Unloads the currently loaded model and releases associated resources.
    ///
    /// Conformers that do not need explicit unloading may rely on the default
    /// no-op implementation provided by the protocol extension.
    func unloadModel() async
}

public extension TranscriptionEngine {
    /// Default implementation — returns `.unknown`.
    /// Conformers that do not distinguish compute units may rely on this default.
    func getComputeUnit() async -> ComputeUnit {
        .unknown
    }

    /// Default no-op implementation.
    /// Existing conformers that do not manage memory explicitly compile without changes.
    func unloadModel() async {}

    func transcribeSegments(
        samples: [Float],
        context: TranscriptionContext
    ) async throws -> [TranscriptionSegment] {
        try [await transcribe(samples: samples, context: context)]
    }
}
