import Foundation
@testable import Business
import Domain
import Testing

// MARK: - Fakes

/// Read-only repository fake. Conforms to `RecordingReadRepository` ONLY —
/// constructing `CleanupTranscriptionUseCase` with this fake is the compile-time
/// proof that the use case is typed against the split read protocol, not the
/// combined `RecordingRepository` (task-009 AC, ports the App-side split).
private actor FakeReadRepository: RecordingReadRepository {
    private let stored: StoredRecording

    init(stored: StoredRecording) {
        self.stored = stored
    }

    func listRecordings(limit _: Int?, offset _: Int?) async throws -> [RecordingSummary] { [] }

    func getRecording(id _: RecordingID) async throws -> StoredRecording { stored }

    func totalStorageSize() async throws -> Int64 { 0 }

    func listPendingSessions() async throws -> [RecordingID] { [] }

    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] { [] }
}

private actor FakeTranscriptReader: TranscriptReadRepository {
    private let draft: String?

    init(draft: String?) {
        self.draft = draft
    }

    func searchTranscripts(query _: String, limit _: Int?, offset _: Int?) async throws -> [RecordingSummary] { [] }

    func getTranscriptDraft(for _: RecordingID) async throws -> String? { draft }
}

private struct TransientStorageFailure: Error {}

/// Write-side fake that can be configured to throw on `saveDraftTranscript`,
/// reproducing the #326 scenario: a transient draft-save failure must not
/// discard the successfully computed cleanup transcript.
private actor FakeTranscriptWriter: TranscriptWriteRepository {
    private let draftSaveError: Error?
    private(set) var savedDrafts: [String] = []
    private(set) var updateTranscriptCallCount = 0
    private(set) var lastUpdatedTranscript: TranscriptionResult?

    init(draftSaveError: Error? = nil) {
        self.draftSaveError = draftSaveError
    }

    func updateTranscript(id _: RecordingID, transcript: TranscriptionResult) async throws {
        updateTranscriptCallCount += 1
        lastUpdatedTranscript = transcript
    }

    func saveDraftTranscript(draftText: String, for _: RecordingID) async throws {
        if let draftSaveError {
            throw draftSaveError
        }
        savedDrafts.append(draftText)
    }
}

private actor FakeTranscriptionEngine: TranscriptionEngine {
    func loadModel(_: ModelID) async throws {}

    func transcribe(samples _: [Float], context _: TranscriptionContext) async throws -> TranscriptionSegment {
        TranscriptionSegment(
            id: SegmentID(UUID().uuidString),
            text: "cleaned text",
            startTime: 0,
            endTime: 1,
            confidence: 0.95,
            isFinal: true,
            sequenceNumber: 0
        )
    }

    func isReady() async -> Bool { true }

    func warmUp() async throws {}
}

private struct FakeSampleLoader: AudioSampleLoader {
    func loadSamples(from _: URL) async throws -> [Float] {
        [Float](repeating: 0, count: 16000)
    }
}

// MARK: - Fixtures

private func makeStoredRecording(id: RecordingID, liveText: String?) -> StoredRecording {
    let metadata = RecordingMetadata(
        id: id,
        recordedAt: Date(timeIntervalSince1970: 1_000_000),
        duration: 1,
        fileSize: 1024,
        audioURL: URL(fileURLWithPath: "/fake/audio.wav"),
        transcriptURL: nil,
        modelId: ModelID("fake-model"),
        processingTime: 0,
        computeUnit: .cpuOnly,
        wordCount: 2
    )
    let transcript = liveText.map { text in
        TranscriptionResult(
            segments: [],
            fullText: text,
            processingTime: 0.1,
            modelId: ModelID("fake-model"),
            recordedAt: Date(timeIntervalSince1970: 1_000_000),
            computeUnit: .cpuOnly,
            passType: .live
        )
    }
    return StoredRecording(metadata: metadata, transcript: transcript)
}

// MARK: - Tests

@Suite("CleanupTranscriptionUseCase #326 fix")
struct CleanupTranscriptionUseCaseFixTests {
    private let recordingId = RecordingID("rec-326")

    private func makeUseCase(
        liveText: String? = "live words",
        existingDraft: String? = nil,
        writer: FakeTranscriptWriter
    ) -> CleanupTranscriptionUseCase {
        CleanupTranscriptionUseCase(
            transcription: FakeTranscriptionEngine(),
            sampleLoader: FakeSampleLoader(),
            reader: FakeReadRepository(stored: makeStoredRecording(id: recordingId, liveText: liveText)),
            transcriptReader: FakeTranscriptReader(draft: existingDraft),
            writer: writer
