import Domain
import Foundation
import Logging
import OSLog

/// Orchestrates a post-recording cleanup transcription pass.
///
/// After a live recording is complete, this use case loads the stored audio
/// file, runs it through a higher-quality transcription model, and returns a
/// refined ``TranscriptionResult`` with ``TranscriptionPassType/cleanup``.
///
/// All external I/O is delegated to injected domain protocols — this actor
/// contains no direct file-system, audio-framework, or inference dependencies.
public actor CleanupTranscriptionUseCase {
    // MARK: - Dependencies

    private let transcription: any TranscriptionEngine
    private let sampleLoader: any AudioSampleLoader
    private let reader: any RecordingRepository
    private let transcriptReader: (any TranscriptReadRepository)?
    private let writer: any TranscriptWriteRepository
    private let telemetry: (any InferenceMetricsRecorder)?

    // MARK: - Logging

    private let logger = Logger(subsystem: "app.the-record", category: "Cleanup")

    // MARK: - Init

    public init(
        transcription: any TranscriptionEngine,
        sampleLoader: any AudioSampleLoader,
        reader: any RecordingRepository,
        transcriptReader: (any TranscriptReadRepository)? = nil,
        writer: any TranscriptWriteRepository,
        telemetry: (any InferenceMetricsRecorder)? = nil
    ) {
        self.transcription = transcription
        self.sampleLoader = sampleLoader
        self.reader = reader
        self.transcriptReader = transcriptReader
        self.writer = writer
        self.telemetry = telemetry
    }

    // MARK: - Execute

    /// Runs the cleanup transcription pass for a stored recording.
    ///
    /// - Parameters:
    ///   - recordingId: Unique identifier of the stored recording to transcribe.
    ///   - modelId: Identifier of the higher-quality model to use for
    ///     the cleanup pass (e.g. `"openai_whisper-base.en"`).
    /// - Returns: A ``TranscriptionResult`` with ``TranscriptionPassType/cleanup``
    ///   containing the refined transcript.
    /// - Throws: Any error produced by the storage, sample loader, or
    ///   transcription engine — errors are never swallowed here.
    public func transcribeCleanupPass(
        recordingId: RecordingID,
        modelId: ModelID
    ) async throws -> TranscriptionResult {
        logger
            .info(
                // swiftlint:disable:next line_length
                "Starting cleanup pass for recording \(recordingId, privacy: .private) with model \(modelId, privacy: .public)"
            )

        let signposter = AppLogger.signposter(category: "Performance")
        let signpostState = signposter.beginInterval("Pipeline Cleanup", id: signposter.makeSignpostID())
        defer { signposter.endInterval("Pipeline Cleanup", signpostState) }

        // 1. Retrieve the stored recording.
        let recording = try await reader.getRecording(id: recordingId)
        logger.info("Retrieved recording: \(recording.metadata.id, privacy: .public)")

        // 2. Extract the audio file URL from the recording metadata.
        let audioURL = recording.metadata.audioURL

        // 3. Load PCM samples and the cleanup model in parallel.
        // checkCancellation between the two async let declarations is intentional:
        // structured concurrency will cancel the started `samples` task on scope exit
        // if this throws, so we can safely start both operations.
        async let samples = sampleLoader.loadSamples(from: audioURL)
        try Task.checkCancellation()
        async let modelLoad: Void = transcription.loadModel(modelId)
        let (loadedSamples, _) = try await (samples, modelLoad)
        logger
            .info(
                // swiftlint:disable:next line_length
                "Loaded \(loadedSamples.count, privacy: .public) PCM samples from \(audioURL.lastPathComponent, privacy: .public)"
            )
        logger.info("Model loaded: \(modelId, privacy: .public)")

        // 4. Build the transcription context for a full-file cleanup pass.
        let context = TranscriptionContext(
            modelId: modelId,
            isFinalChunk: true
        )

        // 5. Transcribe — time the inference for result metadata.
        let startTime = CFAbsoluteTimeGetCurrent()
        try Task.checkCancellation()
        let segments = try await transcription.transcribeSegments(samples: loadedSamples, context: context)
        let computeUnit = await transcription.getComputeUnit()
        let elapsed = CFAbsoluteTimeGetCurrent() - startTime

        logger
            .info(
                // swiftlint:disable:next line_length
                "Cleanup transcription complete in \(elapsed, format: .fixed(precision: 3), privacy: .public)s — \(segments.count, privacy: .public) segments"
            )

        // 5b. Record inference telemetry.
        let audioDuration = Double(loadedSamples.count) / 16000.0
        let avgConfidence = segments.isEmpty ? 0.0 : segments.map(\.confidence).reduce(0, +) / Double(segments.count)
        await telemetry?.record(InferenceMetrics(
            modelId: modelId,
            audioDuration: audioDuration,
            inferenceDuration: elapsed,
            realTimeFactor: elapsed > 0 ? audioDuration / elapsed : 0,
            confidence: avgConfidence,
            sampleCount: loadedSamples.count,
            computeUnit: computeUnit,
            timestamp: Date()
        ))

        // 6. Build the TranscriptionResult with passType .cleanup.
        let fullText = segments.map(\.text).joined(separator: " ")
        let result = TranscriptionResult(
            segments: segments,
            fullText: fullText,
            processingTime: elapsed,
            modelId: modelId,
            recordedAt: recording.metadata.recordedAt,
            computeUnit: computeUnit,
            passType: .cleanup
        )

        // 7a. Save draft of the original live transcript before overwriting (idempotent guard).
        // Skipped when no transcriptReader is injected (can't verify idempotency without it).
        if let transcriptReader {
            let existingDraft = try await transcriptReader.getTranscriptDraft(for: recordingId)
            if existingDraft == nil, let liveText = recording.transcript?.fullText, !liveText.isEmpty {
                try await writer.saveDraftTranscript(draftText: liveText, for: recordingId)
            }
        }

        // 7. Persist the higher-quality cleanup result, overwriting the live pass.
        try await writer.updateTranscript(id: recordingId, transcript: result)
        logger.info("Cleanup transcript persisted for recording \(recordingId, privacy: .public)")

        return result
    }
}

