import Domain
import Foundation
import OSLog

/// Checks for recording sessions that were started but never completed (#161).
///
/// Called once at app launch. A session is pending when `markSessionStarted`
/// ran (e.g. capture began) but `saveRecording` never followed — typically
/// because the app crashed mid-recording.
///
/// Returns the pending IDs. The caller (AppAssembler) feeds each ID into
/// `MenuBarViewModel.recoverPendingSession` for re-transcription and pipeline.
public struct RecoverPendingSessionsUseCase: Sendable {
    private let storage: any RecordingReadRepository
    private let logger = Logger(subsystem: "app.the-record", category: "Recovery")

    public init(storage: some RecordingReadRepository) {
        self.storage = storage
    }

    /// Returns the IDs of all pending sessions and logs a summary.
    ///
    /// - Returns: Pending `RecordingID` values, oldest-first. Empty if none.
    @discardableResult
    public func callAsFunction() async throws -> [RecordingID] {
        let ids = try await storage.listPendingSessions()
        if ids.isEmpty {
            logger.info("Recovery check: no pending sessions found")
        } else {
            logger.warning(
                // swiftlint:disable:next line_length
                "Recovery check: \(ids.count, privacy: .public) pending session(s) found — re-transcribing. IDs: \(ids.map(\.rawValue).joined(separator: ", "), privacy: .private)"
            )
        }
        return ids
    }
}

