import Foundation
@testable import Business
import Domain
import Testing

// MARK: - Fake

/// Read repository fake exposing both recovery lists: crash-mid-capture
/// (`listPendingSessions`) and crash-mid-transcription
/// (`listNeedsRetranscription`, #116).
private actor FakeRecoveryReadRepository: RecordingReadRepository {
    private let pending: [RecordingID]
    private let needsRetranscription: [RecordingID]

    init(pending: [RecordingID], needsRetranscription: [RecordingID]) {
        self.pending = pending
        self.needsRetranscription = needsRetranscription
    }

    func getRecording(id: RecordingID) async throws -> StoredRecording {
        throw StorageError.recordingNotFound(id: id)
    }

    func listRecordings(limit _: Int?, offset _: Int?) async throws -> [RecordingSummary] { [] }

    func totalStorageSize() async throws -> Int64 { 0 }

    func listPendingSessions() async throws -> [RecordingID] { pending }

    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] { [] }

    func listNeedsRetranscription() async throws -> [RecordingID] { needsRetranscription }
}

// MARK: - Tests

@Suite("RecoverPendingSessionsUseCase #116 dedup")
struct RecoverPendingSessionsDedupTests {
    @Test("combines pending and needs-retranscription sessions, pending first")
    func combinesBothRecoveryClasses() async throws {
        let storage = FakeRecoveryReadRepository(
            pending: [RecordingID("rec-a"), RecordingID("rec-b")],
            needsRetranscription: [RecordingID("rec-c")]
        )
        let useCase = RecoverPendingSessionsUseCase(storage: storage)

        let ids = try await useCase()

        #expect(ids == [RecordingID("rec-a"), RecordingID("rec-b"), RecordingID("rec-c")])
    }

    @Test("a session present in both lists is returned exactly once (dedup preserves order)")
    func duplicatePendingSessionsReturnedOnce() async throws {
        let storage = FakeRecoveryReadRepository(
            pending: [RecordingID("rec-a"), RecordingID("rec-dup")],
            needsRetranscription: [RecordingID("rec-dup"), RecordingID("rec-z")]
        )
        let useCase = RecoverPendingSessionsUseCase(storage: storage)

        let ids = try await useCase()

        #expect(ids == [RecordingID("rec-a"), RecordingID("rec-dup"), RecordingID("rec-z")])
    }

    @Test("returns empty when neither recovery class has sessions")
    func emptyWhenNothingToRecover() async throws {
        let storage = FakeRecoveryReadRepository(pending: [], needsRetranscription: [])
        let useCase = RecoverPendingSessionsUseCase(storage: storage)

        let ids = try await useCase()

        #expect(ids.isEmpty)
    }
}

