/// Returns the IDs of all pending sessions and logs a summary.
///
/// Combines two classes of recoverable sessions:
/// - Crash-mid-capture: `listPendingSessions()` (audio was never saved)
/// - Crash-mid-transcription: `listNeedsRetranscription()` (#116) (audio saved, transcription crashed)
///
/// - Returns: Deduplicated `RecordingID` values. Empty if none.
@discardableResult
public func callAsFunction() async throws -> [RecordingID] {
    let pendingIDs = try await storage.listPendingSessions()
    let needsRetranscriptionIDs = try await storage.listNeedsRetranscription()
    // Deduplicate while preserving order: pending first, then needsRetranscription.
    let ids = (pendingIDs + needsRetranscriptionIDs).reduce(into: (seen: Set<RecordingID>(), list: [RecordingID]())) { acc, id in
        guard acc.seen.insert(id).inserted else { return }
        acc.list.append(id)
    }.list

