private actor FakeTranscriptReader: TranscriptReadRepository {
    private let draft: String?

    init(draft: String?) {
        self.draft = draft
    }

    func searchTranscripts(query _: String, limit _: Int?, offset _: Int?) async throws -> [RecordingSummary] { [] }

    func getTranscriptDraft(for _: RecordingID) async throws -> String? { draft }
}

private struct TransientStorageFailure: Error {}

/// Write-side fake that can be configured to throw on `saveDraftTranscript`,
/// reproducing the #326 scenario: a transient draft-save failure must not
/// discard the successfully computed cleanup transcript.
private actor FakeTranscriptWriter: TranscriptWriteRepository {
    private let draftSaveError: Error?
    private(set) var savedDrafts: [String] = []
    private(set) var updateTranscriptCallCount = 0
    private(set) var lastUpdatedTranscript: TranscriptionResult?

    init(draftSaveError: Error? = nil) {
        self.draftSaveError = draftSaveError
    }

    func updateTranscript(id _: RecordingID, transcript: TranscriptionResult) async throws {
        updateTranscriptCallCount += 1
        lastUpdatedTranscript = transcript
    }

    func saveDraftTranscript(draftText: String, for _: RecordingID) async throws {
        if let draftSaveError {
            throw draftSaveError
        }
        savedDrafts.append(draftText)
    }
}

