private func makeTemporaryAudioFile() throws -> URL {
    let dir = FileManager.default.temporaryDirectory
        .appendingPathComponent("DiarizeMeetingUseCaseProtocolTests-\(UUID().uuidString)", isDirectory: true)
    try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
    let sourceURL = dir.appendingPathComponent("source.wav")
    try Data("fake-wav-bytes".utf8).write(to: sourceURL)
    return sourceURL
}

private func makeTranscriptionResult(recordingId: RecordingID) -> TranscriptionResult {
    TranscriptionResult(
        segments: [
            TranscriptionSegment(
                id: SegmentID("seg-0"),
                text: "Hello there",
                startTime: 0,
                endTime: 5,
                confidence: 0.9,
                isFinal: true,
                sequenceNumber: 0
            ),
        ],
        fullText: "Hello there",
        processingTime: 0.5,
        modelId: ModelID("test-model"),
        recordedAt: Date(timeIntervalSince1970: 5_000),
        computeUnit: .cpuOnly
    )
}

// MARK: - Suite

@Suite("task-007 — DiarizeMeetingUseCase / RecordingReadRepository")
struct DiarizeMeetingUseCaseProtocolTests {
    // AC1: DiarizeMeetingUseCase.swift references RecordingReadRepository and compiles.
    @Test("DiarizeMeetingUseCase accepts a RecordingReadRepository and compiles against it")
    func diarizeMeetingUseCaseAcceptsRecordingReadRepository() async throws {
        let recordingId = RecordingID("rec-diarize")
        let sourceURL = try makeTemporaryAudioFile()
        let metadata = makeMetadata(id: recordingId, audioURL: sourceURL)
        let reader = FakeRecordingReadRepository(storedRecording: StoredRecording(metadata: metadata))
        let sampleLoader = FakeAudioSampleLoader(samples: [0.1, 0.2, 0.3])
        let diarization = FakeDiarizationEngine(segments: [
            SpeakerSegment(speakerId: SpeakerID("speaker-0"), startTime: 0, endTime: 5, confidence: 0.95),
        ])
        let writer = FakeDiarizationWriteRepository()

        let useCase = DiarizeMeetingUseCase(
            diarization: diarization,
            sampleLoader: sampleLoader,
            reader: reader,
            writer: writer
        )

        _ = try await useCase.diarize(recordingId: recordingId, transcription: makeTranscriptionResult(recordingId: recordingId))

        let readCalls = await reader.getRecordingCallCount
        #expect(readCalls == 1, "reader.getRecording must be called exactly once through the RecordingReadRepository dependency")
    }

    // AC2: No behavioral change beyond the protocol reference fix — the merge, persistence,
    // and speaker-count behavior of the use case must be unchanged.
    @Test("DiarizeMeetingUseCase preserves existing merge and persistence behavior")
    func diarizeMeetingUseCasePreservesBehavior() async throws {
        let recordingId = RecordingID("rec-behavior")
        let sourceURL = try makeTemporaryAudioFile()
        let metadata = makeMetadata(id: recordingId, audioURL: sourceURL)
        let reader = FakeRecordingReadRepository(storedRecording: StoredRecording(metadata: metadata))
        let sampleLoader = FakeAudioSampleLoader(samples: [0.1, 0.2, 0.3])
        let diarization = FakeDiarizationEngine(segments: [
            SpeakerSegment(speakerId: SpeakerID("speaker-0"), startTime: 0, endTime: 5, confidence: 0.95),
        ])
        let writer = FakeDiarizationWriteRepository()

        let useCase = DiarizeMeetingUseCase(
            diarization: diarization,
            sampleLoader: sampleLoader,
            reader: reader,
            writer: writer
        )

        let result = try await useCase.diarize(
            recordingId: recordingId,
            transcription: makeTranscriptionResult(recordingId: recordingId)
        )

        #expect(result.speakerCount == 1, "one unique speaker segment must produce speakerCount == 1")
        #expect(result.segments.count == 1, "the single transcription segment must map to exactly one diarized segment")
        #expect(
            result.segments.first?.speakerId == SpeakerID("speaker-0"),
            "the diarized segment must carry the overlapping speaker's id, not a placeholder"
        )

        let writeCalls = await writer.attachDiarizationCallCount
        #expect(writeCalls == 1, "attachDiarization must be called exactly once to persist the result")
        let lastId = await writer.lastAttachedId
        #expect(lastId == recordingId, "the exact recording id must be forwarded to attachDiarization")
    }

    // AC3: DiarizeMeetingUseCaseProtocolTests verifies the use case can be constructed
    // and invoked with a fake RecordingReadRepository, returning without throwing.
    @Test("DiarizeMeetingUseCase can be constructed and invoked with a fake RecordingReadRepository")
    func diarizeMeetingUseCaseConstructedAndInvokedWithFake() async throws {
        let recordingId = RecordingID("rec-construct")
        let sourceURL = try makeTemporaryAudioFile()
        let metadata = makeMetadata(id: recordingId, audioURL: sourceURL)
        let reader = FakeRecordingReadRepository(storedRecording: StoredRecording(metadata: metadata))
        let sampleLoader = FakeAudioSampleLoader(samples: [0.1, 0.2, 0.3])
        let diarization = FakeDiarizationEngine(segments: [])
        let writer = FakeDiarizationWriteRepository()

        let useCase = DiarizeMeetingUseCase(
            diarization: diarization,
            sampleLoader: sampleLoader,
            reader: reader,
            writer: writer
        )

        let result = try await useCase.diarize(
            recordingId: recordingId,
            transcription: makeTranscriptionResult(recordingId: recordingId)
        )

        #expect(result.speakerCount == 0, "no speaker segments must yield speakerCount == 0")
        #expect(
            result.segments.first?.speakerId == SpeakerID.unknown,
            "with no overlapping speaker segments the transcript segment must be labelled Unknown"
        )
    }
}

