import Testing
import Foundation
@testable import Business
import Domain
import TestMocks

// MARK: - Factories

private func makeStoredRecordingForDiarization(
    id: RecordingID = RecordingID("recording-001"),
    audioURL: URL = URL(fileURLWithPath: "/recordings/test-audio.wav"),
) -> StoredRecording {
    let meta = RecordingMetadata(
        id: id,
        recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
        duration: 120.0,
        fileSize: 2_097_152,
        audioURL: audioURL,
        transcriptURL: nil,
        modelId: ModelID("openai_whisper-tiny"),
        processingTime: 2.0,
        computeUnit: .cpuAndNeuralEngine,
        wordCount: 0,
    )
    return StoredRecording(metadata: meta)
}

private func makeTranscriptionResultForDiarization() -> TranscriptionResult {
    let segments = [
        TranscriptionSegment(
            id: SegmentID("seg-0"),
            text: "Hello world",
            startTime: 0.0,
            endTime: 5.0,
            confidence: 0.9,
            isFinal: true,
            sequenceNumber: 0,
        ),
        TranscriptionSegment(
            id: SegmentID("seg-1"),
            text: "How are you",
            startTime: 5.0,
            endTime: 10.0,
            confidence: 0.8,
            isFinal: true,
            sequenceNumber: 1,
        ),
        TranscriptionSegment(
            id: SegmentID("seg-2"),
            text: "I am fine",
            startTime: 10.0,
            endTime: 15.0,
            confidence: 0.85,
            isFinal: true,
            sequenceNumber: 2,
        ),
    ]
    return TranscriptionResult(
        segments: segments,
        fullText: "Hello world How are you I am fine",
        processingTime: 1.0,
        modelId: ModelID("openai_whisper-tiny"),
        recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
        computeUnit: .cpuAndNeuralEngine,
        passType: .cleanup,
    )
}

/// Builds a two-segment transcription where `seg-gap` (20–25 s) falls outside
/// all speaker coverage, used to verify the "Unknown" fallback.
private func makeTranscriptionWithGapSegment() -> TranscriptionResult {
    let segments = [
        TranscriptionSegment(
            id: SegmentID("seg-0"),
            text: "Hello",
            startTime: 0.0,
            endTime: 5.0,
            confidence: 0.9,
            isFinal: true,
            sequenceNumber: 0,
        ),
        TranscriptionSegment(
            id: SegmentID("seg-gap"),
            text: "Gap segment",
            startTime: 20.0,
            endTime: 25.0,
            confidence: 0.7,
            isFinal: true,
            sequenceNumber: 1,
        ),
    ]
    return TranscriptionResult(
        segments: segments,
        fullText: "Hello Gap segment",
        processingTime: 1.0,
        modelId: ModelID("openai_whisper-tiny"),
        recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
        computeUnit: .cpuAndNeuralEngine,
        passType: .cleanup,
    )
}

/// speaker-0 covers 0–7 s, speaker-1 covers 7–15 s.
/// Expected assignments:
///   seg-0 (0-5):   overlap speaker-0 = 5.0, speaker-1 = 0.0 → speaker-0
///   seg-1 (5-10):  overlap speaker-0 = 2.0, speaker-1 = 3.0 → speaker-1
///   seg-2 (10-15): overlap speaker-0 = 0.0, speaker-1 = 5.0 → speaker-1
private func makeSpeakerSegmentsForDiarization() -> [SpeakerSegment] {
    [
        SpeakerSegment(speakerId: SpeakerID("speaker-0"), startTime: 0.0, endTime: 7.0, confidence: 0.9),
