    private let segments: [SpeakerSegment]
    private let diarizeError: Error?

    private(set) var prepareCalled = false
    private(set) var diarizeCalled = false

    init(
        ready: Bool = true,
        prepareError: Error? = nil,
        segments: [SpeakerSegment] = [],
        diarizeError: Error? = nil
    ) {
        self.ready = ready
        self.prepareError = prepareError
        self.segments = segments
        self.diarizeError = diarizeError
    }

    func isReady() async -> Bool { ready }

    func prepare() async throws {
        prepareCalled = true
        if let prepareError { throw prepareError }
        ready = true
    }

    func diarize(samples _: [Float], sampleRate _: Int) async throws -> [SpeakerSegment] {
        diarizeCalled = true
        if let diarizeError { throw diarizeError }
        return segments
    }
}

