// MARK: - Capture

/// Thread-safe recorder for (CleanupState, PipelineState) pairs emitted by the
/// coordinator's consolidated `onStateChange` callback.
private final class StatePairRecorder: @unchecked Sendable {
    private let lock = NSLock()
    private var storage: [(CleanupState, PipelineState)] = []

    func append(_ cleanup: CleanupState, _ pipeline: PipelineState) {
        lock.lock()
        storage.append((cleanup, pipeline))
        lock.unlock()
    }

    var pairs: [(CleanupState, PipelineState)] {
        lock.lock()
        defer { lock.unlock() }
        return storage
    }
}

