import Foundation

public struct StreamingSegment: Sendable, Identifiable {
    public let id: SegmentID
    public let text: String
    public let isFinal: Bool
    public let track: AudioTrack
    public let speakerId: SpeakerID?
    public let timestamp: TimeInterval
    /// Whether this segment represents a transcription error rather than valid
    /// text. When `true`, `text` is empty and `errorMessage` carries the
    /// localized failure description.
    public let isError: Bool
    /// The localized error description when `isError` is `true`; `nil` for
    /// normal segments.
    public let errorMessage: String?
    /// Whether this segment has been translated from its original language.
    /// `false` for raw transcription output; `true` only after a successful
    /// translation engine call.
    public let isTranslated: Bool

    public init(
        text: String,
        isFinal: Bool,
        track: AudioTrack,
        speakerId: SpeakerID? = nil,
        timestamp: TimeInterval,
        isError: Bool = false,
        errorMessage: String? = nil,
        isTranslated: Bool = false,
        id: SegmentID = .generate()
    ) {
        self.id = id
        self.text = text
        self.isFinal = isFinal
        self.track = track
        self.speakerId = speakerId
        self.timestamp = timestamp
        self.isError = isError
        self.errorMessage = errorMessage
        self.isTranslated = isTranslated
    }
}

public struct TranslatedSegment: Sendable {
    public let original: StreamingSegment
    public let translatedText: String
    public let targetLanguage: String

    public init(original: StreamingSegment, translatedText: String, targetLanguage: String) {
        self.original = original
        self.translatedText = translatedText
        self.targetLanguage = targetLanguage
    }
}

import Foundation

public enum AudioTrack: String, Sendable, Codable, Equatable {
    case system
    case microphone
}

public struct TaggedAudioBuffer: Sendable {
    public let buffer: AudioBuffer
    public let track: AudioTrack
    public let timestamp: TimeInterval

    public init(buffer: AudioBuffer, track: AudioTrack, timestamp: TimeInterval) {
        self.buffer = buffer
        self.track = track
        self.timestamp = timestamp
    }

    /// Returns a silent `.system` buffer time-aligned with `mic`.
    ///
    /// Used as a placeholder far-end reference when the system audio stream is
    /// not co-routed through AEC. Speex pads/truncates to its internal frame
    /// size, so sample count here does not need to match exactly.
    public static func silentFarEnd(matching mic: TaggedAudioBuffer) -> TaggedAudioBuffer {
        let silent = AudioBuffer(
            sampleRate: mic.buffer.sampleRate,
            channelCount: mic.buffer.channelCount,
            samples: [Float](repeating: 0, count: mic.buffer.samples.count),
            timestamp: mic.buffer.timestamp
        )
        return TaggedAudioBuffer(buffer: silent, track: .system, timestamp: mic.timestamp)
    }
}

