import Foundation
@testable import Business
import Domain
import Testing

// MARK: - Fakes

private struct ScriptedEngineError: Error {}
private struct ModelLoadError: Error {}
private struct UpstreamCaptureError: Error {}

/// Transcription engine driven by a per-call script: each `transcribe` call
/// consumes the next entry, either returning that text or throwing. Records
/// every context and loaded model so tests can assert resume and fallback
/// semantics.
private actor ScriptedTranscriptionEngine: TranscriptionEngine {
    enum Step: Sendable {
        case text(String)
        case failure
    }

    private var script: [Step]
    private let failingModels: Set<ModelID>
    private let ready: Bool

    private(set) var loadedModels: [ModelID] = []
    private(set) var transcribeCallCount = 0
    private(set) var contexts: [TranscriptionContext] = []

    init(script: [Step], failingModels: Set<ModelID> = [], ready: Bool = true) {
        self.script = script
        self.failingModels = failingModels
        self.ready = ready
    }

    func loadModel(_ modelId: ModelID) async throws {
        if failingModels.contains(modelId) { throw ModelLoadError() }
        loadedModels.append(modelId)
    }

    func transcribe(samples _: [Float], context: TranscriptionContext) async throws -> TranscriptionSegment {
        transcribeCallCount += 1
        contexts.append(context)
        let step = script.isEmpty ? Step.text("") : script.removeFirst()
        switch step {
        case .failure:
            throw ScriptedEngineError()
        case let .text(text):
            return TranscriptionSegment(
                id: SegmentID("seg-\(transcribeCallCount)"),
                text: text,
                startTime: context.timestampOffset,
                endTime: context.timestampOffset + 1,
                confidence: 0.9,
                isFinal: false,
                sequenceNumber: transcribeCallCount
            )
        }
    }

    func isReady() async -> Bool { ready }
    func warmUp() async throws {}
}

// MARK: - Fixtures

private func makeBuffer(timestamp: TimeInterval, track: AudioTrack = .microphone) -> TaggedAudioBuffer {
    TaggedAudioBuffer(
        buffer: AudioBuffer(sampleRate: 16000, channelCount: 1, samples: [0.1, 0.2, 0.3], timestamp: timestamp),
        track: track,
        timestamp: timestamp
    )
}

private func makeInputStream(
    buffers: [TaggedAudioBuffer],
    terminalError: Error? = nil
) -> AsyncThrowingStream<TaggedAudioBuffer, any Error> {
    AsyncThrowingStream { continuation in
        for buffer in buffers {
            continuation.yield(buffer)
        }
        continuation.finish(throwing: terminalError)
    }
}

private func collect(_ stream: AsyncStream<StreamingSegment>) async -> [StreamingSegment] {
    var segments: [StreamingSegment] = []
    for await segment in stream {
        segments.append(segment)
    }
    return segments
}

// MARK: - Suite

@Suite("task-013 — StreamingTranscriptionUseCase App-side parity")
struct StreamingTranscriptionUseCaseTests {
    // Happy path: each buffer becomes one segment carrying its track and timestamp.
    @Test("happy path yields one segment per buffer with track and timestamp preserved")
    func happyPathYieldsSegmentsInOrder() async throws {
        let engine = ScriptedTranscriptionEngine(script: [.text("first"), .text("second")])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [
            makeBuffer(timestamp: 0, track: .microphone),
            makeBuffer(timestamp: 1, track: .system),
        ])

        let segments = await collect(useCase.transcribeStream(input, modelId: ModelID("m")))

        #expect(segments.count == 2)
        #expect(segments[0].text == "first")
        #expect(segments[0].track == .microphone)
        #expect(segments[0].timestamp == 0)
        #expect(segments[1].text == "second")
        #expect(segments[1].track == .system)
        #expect(segments[1].timestamp == 1)
        #expect(segments.allSatisfy { !$0.isError })
    }

    @Test("empty and whitespace-only segments are filtered out")
    func emptySegmentsAreFiltered() async throws {
        let engine = ScriptedTranscriptionEngine(script: [.text(""), .text("   "), .text("real")])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [
            makeBuffer(timestamp: 0), makeBuffer(timestamp: 1), makeBuffer(timestamp: 2),
        ])

        let segments = await collect(useCase.transcribeStream(input, modelId: ModelID("m")))

        #expect(segments.count == 1)
        #expect(segments.first?.text == "real")
    }

    @Test("consecutive duplicate (text, track) segments are deduplicated")
    func consecutiveDuplicatesAreDropped() async throws {
        let engine = ScriptedTranscriptionEngine(script: [.text("same"), .text("same"), .text("new")])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [
            makeBuffer(timestamp: 0), makeBuffer(timestamp: 1), makeBuffer(timestamp: 2),
        ])

        let segments = await collect(useCase.transcribeStream(input, modelId: ModelID("m")))

        #expect(segments.map(\.text) == ["same", "new"])
    }

    // Resume-after-interruption: a mid-stream transcription failure is
    // transient — the loop surfaces an error segment, then picks up with the
    // next buffer from the last committed segment instead of restarting.
    @Test("resume after interruption: transient failure yields error segment then continues from last committed segment")
    func resumeAfterInterruptionContinuesFromLastCommittedSegment() async throws {
        let engine = ScriptedTranscriptionEngine(script: [.text("one"), .failure, .text("three")])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [
            makeBuffer(timestamp: 0), makeBuffer(timestamp: 1), makeBuffer(timestamp: 2),
        ])

        let segments = await collect(useCase.transcribeStream(input, modelId: ModelID("m")))

        #expect(segments.count == 3, "expected committed, error, resumed segments — got \(segments.map(\.text))")
        #expect(segments[0].text == "one")
        #expect(segments[1].isError, "the interrupted chunk must surface as an error segment")
        #expect(segments[1].isFinal == false, "a transient per-chunk failure must not be terminal")
        #expect(segments[1].errorMessage != nil)
        #expect(segments[2].text == "three", "stream must resume with the next buffer, not restart")
        #expect(segments[2].isError == false)

        // The engine was never re-driven over already-committed buffers.
        #expect(await engine.transcribeCallCount == 3)
        let offsets = await engine.contexts.map(\.timestampOffset)
        #expect(offsets == [0, 1, 2], "resume must continue from the buffer after the interruption")
    }

    // Terminal error: upstream capture failure ends the stream with a single
    // terminal error segment after all committed segments.
    @Test("upstream capture failure yields a terminal error segment and finishes the stream")
    func upstreamFailureIsTerminal() async throws {
        let engine = ScriptedTranscriptionEngine(script: [.text("committed")])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [makeBuffer(timestamp: 0)], terminalError: UpstreamCaptureError())

        let segments = await collect(useCase.transcribeStream(input, modelId: ModelID("m")))

        #expect(segments.count == 2)
        #expect(segments[0].text == "committed")
        #expect(segments[1].isError, "capture failure must surface as an error segment")
        #expect(segments.last?.isError == true, "the error segment must be the last emission before finish")
    }

    @Test("model load failure with engine not ready aborts with a single terminal error segment")
    func modelLoadFailureAbortsStream() async throws {
        let modelId = ModelID("broken")
        let engine = ScriptedTranscriptionEngine(script: [.text("never")], failingModels: [modelId], ready: false)
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [makeBuffer(timestamp: 0)])

        let segments = await collect(useCase.transcribeStream(input, modelId: modelId))

        #expect(segments.count == 1)
        #expect(segments.first?.isError == true)
        #expect(segments.first?.isFinal == true, "a load abort is terminal")
        #expect(await engine.transcribeCallCount == 0, "no buffer may be transcribed after a load abort")
    }

    @Test("model load failure with engine already ready continues streaming")
    func modelLoadFailureWithReadyEngineContinues() async throws {
        let modelId = ModelID("broken")
        let engine = ScriptedTranscriptionEngine(script: [.text("still works")], failingModels: [modelId], ready: true)
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [makeBuffer(timestamp: 0)])

        let segments = await collect(useCase.transcribeStream(input, modelId: modelId))

        #expect(segments.count == 1)
        #expect(segments.first?.text == "still works")
        #expect(segments.first?.isError == false)
    }

    // Fallback overload: preferred model load failure falls back and streams
    // with the fallback model id in every transcription context.
    @Test("fallback overload uses fallback model when preferred load fails")
    func fallbackOverloadFallsBack() async throws {
        let preferred = ModelID("preferred")
        let fallback = ModelID("fallback")
        let engine = ScriptedTranscriptionEngine(script: [.text("via fallback")], failingModels: [preferred])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [makeBuffer(timestamp: 0)])

        let segments = await collect(useCase.transcribeStream(input, preferredModelId: preferred, fallbackModelId: fallback))

        #expect(segments.count == 1)
        #expect(segments.first?.text == "via fallback")
        #expect(await engine.loadedModels == [fallback])
        #expect(await engine.contexts.first?.modelId == fallback)
    }

    @Test("fallback overload resume after interruption matches primary overload semantics")
    func fallbackOverloadResumesAfterInterruption() async throws {
        let engine = ScriptedTranscriptionEngine(script: [.text("one"), .failure, .text("three")])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [
            makeBuffer(timestamp: 0), makeBuffer(timestamp: 1), makeBuffer(timestamp: 2),
        ])

        let segments = await collect(useCase.transcribeStream(
            input,
            preferredModelId: ModelID("m"),
            fallbackModelId: ModelID("f")
        ))

        #expect(segments.map(\.isError) == [false, true, false])
        #expect(segments[0].text == "one")
        #expect(segments[2].text == "three")
    }

    @Test("fallback overload aborts with terminal error when both model loads fail")
    func fallbackOverloadAbortsWhenBothLoadsFail() async throws {
        let preferred = ModelID("preferred")
        let fallback = ModelID("fallback")
        let engine = ScriptedTranscriptionEngine(script: [.text("never")], failingModels: [preferred, fallback])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [makeBuffer(timestamp: 0)])

        let segments = await collect(useCase.transcribeStream(input, preferredModelId: preferred, fallbackModelId: fallback))

        #expect(segments.count == 1)
        #expect(segments.first?.isError == true)
        #expect(segments.first?.isFinal == true)
        #expect(await engine.transcribeCallCount == 0)
    }
}

