                            isFinal: true,
                            track: .microphone,
                            timestamp: 0,
                            isError: true,
                            errorMessage: error.localizedDescription
                        ))
                        continuation.finish()
                        return
                    }
                }

                await Self.runTranscriptionLoop(
                    stream: stream,
                    modelId: modelId,
                    transcription: transcription,
                    logger: logger,
                    continuation: continuation
