import Foundation

/// Domain errors surfaced by ContextProvider implementations (e.g. GenericMCPProvider).
public enum MCPError: Error, Sendable, Equatable, UserFacingError {
    /// The remote MCP server returned a non-2xx HTTP status code.
    case httpError(statusCode: Int)
    /// A transport-level failure (e.g. connection refused, timeout).
    case transportError(description: String)
    /// No credential is stored in the Keychain for this provider.
    case missingCredential

    // MARK: - UserFacingError

    public var userMessage: String {
        switch self {
        case let .httpError(statusCode):
            "MCP server returned HTTP \(statusCode). Please check the server status."
        case .transportError:
            "Connection to context provider failed. Please check your network."
        case .missingCredential:
            "No API key found for this provider. Add one in Settings → Integrations."
        }
    }

    public var debugDescription: String {
        switch self {
        case let .httpError(statusCode):
            "MCPError.httpError(statusCode: \(statusCode))"
        case let .transportError(description):
            "MCPError.transportError(description: \(description))"
        case .missingCredential:
            "MCPError.missingCredential"
        }
    }
}

import Foundation

/// Reads and writes a single HuggingFace API token to a secure store.
///
/// The live implementation persists the token in the macOS Keychain
/// (`HFTokenKeychain`). Tests inject a mock to avoid Keychain access.
public protocol TokenStore: Sendable {
    /// Returns the stored token, or `nil` if none exists.
    func loadToken() throws -> String?
    /// Persists `token`, replacing any existing value.
    func saveToken(_ token: String) throws
    /// Removes the stored token. A no-op when no token is present.
    func deleteToken() throws
}

