import Domain
import Foundation
import Testing

// MARK: - TokenStore fake (Record-Foundation surface)

/// Conforms to `TokenStore` implementing exactly the Record-Foundation-side
/// surface: loadToken/saveToken/deleteToken. Fails to compile if the
/// CrossPlatform protocol adds, removes, or reshapes a requirement.
private final class InMemoryTokenStore: TokenStore, @unchecked Sendable {
    private let lock = NSLock()
    private var token: String?

    func loadToken() throws -> String? {
        lock.lock()
        defer { lock.unlock() }
        return token
    }

    func saveToken(_ token: String) throws {
        lock.lock()
        defer { lock.unlock() }
        self.token = token
    }

    func deleteToken() throws {
        lock.lock()
        defer { lock.unlock() }
        token = nil
    }
}

// MARK: - Suite

@Suite("task-014 — Domain dedup: MCPError / TokenStore parity with Record-Foundation")
struct DomainDedupTests {
    // Exhaustive switch (no default) over every case present in
    // Record-Foundation's MCPError — fails to compile if the CrossPlatform
    // copy drops a case, and flags via review if it gains one.
    @Test("MCPError carries every Record-Foundation case with matching payloads")
    func mcpErrorCasesMatchRecordFoundation() throws {
        let allCases: [MCPError] = [
            .httpError(statusCode: 503),
            .transportError(description: "connection refused"),
            .missingCredential,
        ]

        for error in allCases {
            switch error {
            case let .httpError(statusCode):
                #expect(statusCode == 503)
                #expect(error.userMessage.contains("503"))
                #expect(error.debugDescription == "MCPError.httpError(statusCode: 503)")
            case let .transportError(description):
                #expect(description == "connection refused")
                #expect(!error.userMessage.isEmpty)
                #expect(error.debugDescription.contains("connection refused"))
            case .missingCredential:
                #expect(!error.userMessage.isEmpty)
                #expect(error.debugDescription == "MCPError.missingCredential")
            }
        }
    }

    @Test("MCPError conforms to Equatable and UserFacingError as in Record-Foundation")
    func mcpErrorConformancesMatchRecordFoundation() throws {
        #expect(MCPError.httpError(statusCode: 404) == MCPError.httpError(statusCode: 404))
        #expect(MCPError.httpError(statusCode: 404) != MCPError.missingCredential)

        let userFacing: any UserFacingError = MCPError.missingCredential
        #expect(!userFacing.userMessage.isEmpty)
    }

    // A fake implementing the Record-Foundation-side TokenStore surface must
    // satisfy the CrossPlatform protocol and round-trip a token.
    @Test("TokenStore requirements are satisfiable by a Record-Foundation-surface fake")
    func tokenStoreRequirementsMatchRecordFoundation() throws {
        let store: any TokenStore = InMemoryTokenStore()

        #expect(try store.loadToken() == nil)

        try store.saveToken("hf_test_token")
        #expect(try store.loadToken() == "hf_test_token")

        try store.saveToken("hf_replaced")
        #expect(try store.loadToken() == "hf_replaced", "saveToken must replace any existing value")

        try store.deleteToken()
        #expect(try store.loadToken() == nil)

        try store.deleteToken()
        #expect(try store.loadToken() == nil, "deleteToken must be a no-op when no token is present")
    }
}

// swiftlint:disable function_body_length
// The two transcribeStream overloads each wrap a nonisolated async Task state machine.
// SwiftLint counts the Task closure body as function body length; splitting further
// requires crossing Swift 6 nonisolated/Sendable boundaries unsafely. Disable is scoped
// to this file only.
import Domain
import Foundation
import OSLog

/// Consumes a tagged audio buffer stream and yields transcribed streaming
/// segments in real time.
///
/// Each ``TaggedAudioBuffer`` is transcribed independently via the injected
/// ``TranscriptionEngine``. The resulting ``StreamingSegment`` carries the
/// buffer's track and timestamp so downstream consumers can associate text
/// with its audio source without additional bookkeeping.
public actor StreamingTranscriptionUseCase {
    // MARK: - Dependencies

    private let transcription: any TranscriptionEngine

    // MARK: - Logging

    private let logger = Logger(subsystem: "app.the-record", category: "StreamingTranscription")

    // MARK: - Init

    public init(transcription: any TranscriptionEngine) {
        self.transcription = transcription
    }

    // MARK: - Execute

    /// Transcribes each buffer in `stream` and returns a live stream of
    /// ``StreamingSegment`` values.
    ///
    /// - Parameters:
    ///   - stream: An ``AsyncStream`` of ``TaggedAudioBuffer`` values produced
    ///     by the audio capture pipeline.
    ///   - modelId: The model variant identifier forwarded to the engine.
    /// - Returns: An ``AsyncStream`` that yields one ``StreamingSegment`` per
    ///   consumed buffer and finishes when the input stream is exhausted.
    public nonisolated func transcribeStream(
        _ stream: AsyncThrowingStream<TaggedAudioBuffer, any Swift.Error>,
        modelId: ModelID
    ) -> AsyncStream<StreamingSegment> {
        // SAFETY: TranscriptionEngine must be Sendable for nonisolated capture in StreamingTranscriptionUseCase
        let transcription = transcription
        let logger = logger

        return AsyncStream(bufferingPolicy: .bufferingNewest(32)) { continuation in
            // NOTE: This Task is unstructured — cancellation flows via continuation.onTermination below.
            // If the caller cancels the stream, onTermination fires and cancels this task.
            let task = Task {
                logger.info("Streaming transcription started; modelId=\(modelId.rawValue, privacy: .public)")

                // Pre-warm unconditionally — loadModel is idempotent when the model is
                // already loaded, and isReady() returning true only means *some* model is
                // ready, not necessarily this one.
                do {
                    try await transcription.loadModel(modelId)
                } catch {
                    // If the engine is already ready (loaded via another path), proceed.
                    // If it is not ready, abort — transcription cannot succeed.
                    let alreadyReady = await transcription.isReady()
                    if alreadyReady {
                        logger
                            .warning(
                                // swiftlint:disable:next line_length
                                "Model load failed; engine already ready — continuing: \(String(reflecting: error), privacy: .private)"
                            )
                    } else {
                        logger
                            .error("Model load failed, aborting stream: \(String(reflecting: error), privacy: .public)")
                        continuation.yield(StreamingSegment(
                            text: "",
                            isFinal: true,
                            track: .microphone,
                            timestamp: 0,
                            isError: true,
                            errorMessage: error.localizedDescription
                        ))
                        continuation.finish()
                        return
                    }
                }

                await Self.runTranscriptionLoop(
                    stream: stream,
                    modelId: modelId,
                    transcription: transcription,
                    logger: logger,
                    continuation: continuation
                )

                continuation.finish()
                logger.info("Streaming transcription finished")
            }
            continuation.onTermination = { [task] _ in task.cancel() }
        }
    }

    /// Tries to load `preferredModelId` before streaming; falls back to `fallbackModelId`
    /// on load failure. Once a model is successfully loaded the stream runs identically
    /// to `transcribeStream(_:modelId:)`.
    public nonisolated func transcribeStream(
        _ stream: AsyncThrowingStream<TaggedAudioBuffer, any Swift.Error>,
        preferredModelId: ModelID,
        fallbackModelId: ModelID
    ) -> AsyncStream<StreamingSegment> {
        let transcription = transcription
        let logger = logger
        return AsyncStream(bufferingPolicy: .bufferingNewest(32)) { continuation in
            let task = Task {
                // Always attempt to load the preferred model — loadModel is idempotent
                // when the same model is already loaded. Never branch on isReady() alone:
                // it returns true if *any* model is loaded, not necessarily the preferred one.
                let modelId: ModelID
                do {
                    try await transcription.loadModel(preferredModelId)
                    modelId = preferredModelId
                    logger.info("Streaming: using preferred model \(preferredModelId.rawValue, privacy: .public)")
                } catch {
                    logger
                        .warning(
                            // swiftlint:disable:next line_length
                            "Preferred model \(preferredModelId.rawValue, privacy: .public) unavailable — falling back to \(fallbackModelId.rawValue, privacy: .public): \(String(reflecting: error), privacy: .private)"
                        )
                    do {
                        try await transcription.loadModel(fallbackModelId)
                        modelId = fallbackModelId
                    } catch let fallbackError {
                        logger
                            .error("Fallback model load failed: \(String(reflecting: fallbackError), privacy: .public)")
                        continuation.yield(StreamingSegment(
                            text: "", isFinal: true, track: .microphone, timestamp: 0,
                            isError: true, errorMessage: fallbackError.localizedDescription
                        ))
                        continuation.finish()
                        return
                    }
                }

                await Self.runTranscriptionLoop(
                    stream: stream,
                    modelId: modelId,
                    transcription: transcription,
                    logger: logger,
                    continuation: continuation,
                    errorLogSuffix: " (fallback overload)"
                )

                continuation.finish()
                logger.info("Streaming transcription finished (model: \(modelId.rawValue, privacy: .public))")
            }
            continuation.onTermination = { [task] _ in task.cancel() }
        }
    }

    // MARK: - Shared streaming loop (F17)

    /// Consumes `stream`, transcribes each buffer, and yields ``StreamingSegment``
    /// values to `continuation`. Shared by both `transcribeStream` overloads —
    /// the only thing that differs between the two call sites is how `modelId`
    /// was resolved before the loop starts and the error-log label used when a
    /// per-chunk transcription fails.
    ///
    /// Filters empty/whitespace-only segments, deduplicates consecutive
    /// (text, track) repeats, logs and surfaces per-chunk transcription
    /// failures as error segments without terminating the stream, and warns
    /// when the output buffer (`bufferingNewest(32)`) drops a segment because
    /// the consumer is not keeping up. On upstream capture failure, yields a
    /// single terminal error segment.
    ///
    /// - Parameters:
    ///   - stream: The input buffer stream to consume.
    ///   - modelId: The model identifier already loaded by the caller, forwarded
    ///     into each ``TranscriptionContext``.
    ///   - transcription: The engine used to transcribe each buffer.
    ///   - logger: The logger to use for per-chunk and stream-level diagnostics.
    ///   - continuation: The output stream continuation to yield segments to.
    ///   - errorLogSuffix: Appended to the "Transcription failed" log label so
    ///     call sites remain distinguishable in logs (e.g. " (fallback overload)").
    private static func runTranscriptionLoop(
        stream: AsyncThrowingStream<TaggedAudioBuffer, any Swift.Error>,
        modelId: ModelID,
        transcription: any TranscriptionEngine,
        logger: Logger,
        continuation: AsyncStream<StreamingSegment>.Continuation,
        errorLogSuffix: String = ""
    ) async {
        var lastYieldedText: String?
        var lastYieldedTrack: AudioTrack?

        do {
            for try await taggedBuffer in stream {
                try Task.checkCancellation()
                await Task.yield()

                let context = TranscriptionContext(
                    modelId: modelId,
                    isFinalChunk: false,
                    timestampOffset: taggedBuffer.timestamp
                )

                do {
                    let segment = try await transcription.transcribe(
                        samples: taggedBuffer.buffer.samples,
                        context: context
                    )

                    // Drop empty/whitespace segments — upstream filter so the VM
                    // never receives segments with no displayable content.
                    guard !segment.text.trimmingCharacters(in: .whitespaces).isEmpty else {
                        continue
                    }

                    // Drop consecutive duplicates — same text+track re-emitted back-to-back.
                    if segment.text == lastYieldedText, taggedBuffer.track == lastYieldedTrack {
                        continue
                    }

                    let streamingSegment = StreamingSegment(
                        text: segment.text,
                        isFinal: segment.isFinal,
                        track: taggedBuffer.track,
                        timestamp: taggedBuffer.timestamp
                    )

                    let trk = taggedBuffer.track.rawValue
                    let ts = taggedBuffer.timestamp
                    logger.debug(
                        // swiftlint:disable:next line_length
                        "Segment yielded: track=\(trk, privacy: .public) ts=\(ts, format: .fixed(precision: 3), privacy: .public)s text=\(segment.text.prefix(60), privacy: .private)"
                    )

                    lastYieldedText = segment.text
                    lastYieldedTrack = taggedBuffer.track
                    if case .dropped = continuation.yield(streamingSegment) {
                        logger
                            .warning(
                                "Streaming segment dropped — bufferingNewest(32) full; transcript may be incomplete"
                            )
                    }
                } catch {
                    let trk2 = taggedBuffer.track.rawValue
                    let ts2 = taggedBuffer.timestamp
                    logger.error(
                        // swiftlint:disable:next line_length
                        "Transcription failed\(errorLogSuffix): track=\(trk2, privacy: .public) ts=\(ts2, format: .fixed(precision: 3), privacy: .public)s error=\(String(reflecting: error), privacy: .private)"
                    )
                    continuation.yield(StreamingSegment(
                        text: "",
                        isFinal: false,
                        track: taggedBuffer.track,
                        timestamp: taggedBuffer.timestamp,
                        isError: true,
                        errorMessage: error.localizedDescription
                    ))
                }
            }
        } catch {
            let errDesc = String(reflecting: error)
            logger.error("Capture stream failed: \(errDesc, privacy: .private)")
            continuation.yield(StreamingSegment(
                text: "",
                isFinal: false,
                track: .microphone,
                timestamp: 0,
                isError: true,
                errorMessage: error.localizedDescription
            ))
        }
    }
}

import Foundation
@testable import Business
import Domain
import Testing

// MARK: - Fakes

private struct ScriptedEngineError: Error {}
private struct ModelLoadError: Error {}
private struct UpstreamCaptureError: Error {}

/// Transcription engine driven by a per-call script: each `transcribe` call
/// consumes the next entry, either returning that text or throwing. Records
/// every context and loaded model so tests can assert resume and fallback
/// semantics.
private actor ScriptedTranscriptionEngine: TranscriptionEngine {
    enum Step: Sendable {
        case text(String)
        case failure
    }

    private var script: [Step]
    private let failingModels: Set<ModelID>
    private let ready: Bool

    private(set) var loadedModels: [ModelID] = []
    private(set) var transcribeCallCount = 0
    private(set) var contexts: [TranscriptionContext] = []

    init(script: [Step], failingModels: Set<ModelID> = [], ready: Bool = true) {
        self.script = script
        self.failingModels = failingModels
        self.ready = ready
    }

    func loadModel(_ modelId: ModelID) async throws {
        if failingModels.contains(modelId) { throw ModelLoadError() }
        loadedModels.append(modelId)
    }

    func transcribe(samples _: [Float], context: TranscriptionContext) async throws -> TranscriptionSegment {
        transcribeCallCount += 1
        contexts.append(context)
        let step = script.isEmpty ? Step.text("") : script.removeFirst()
        switch step {
        case .failure:
            throw ScriptedEngineError()
        case let .text(text):
            return TranscriptionSegment(
                id: SegmentID("seg-\(transcribeCallCount)"),
                text: text,
                startTime: context.timestampOffset,
                endTime: context.timestampOffset + 1,
                confidence: 0.9,
                isFinal: false,
                sequenceNumber: transcribeCallCount
            )
        }
    }

    func isReady() async -> Bool { ready }
    func warmUp() async throws {}
}

// MARK: - Fixtures

private func makeBuffer(timestamp: TimeInterval, track: AudioTrack = .microphone) -> TaggedAudioBuffer {
    TaggedAudioBuffer(
        buffer: AudioBuffer(sampleRate: 16000, channelCount: 1, samples: [0.1, 0.2, 0.3], timestamp: timestamp),
        track: track,
        timestamp: timestamp
    )
}

private func makeInputStream(
    buffers: [TaggedAudioBuffer],
    terminalError: Error? = nil
) -> AsyncThrowingStream<TaggedAudioBuffer, any Error> {
    AsyncThrowingStream { continuation in
        for buffer in buffers {
            continuation.yield(buffer)
        }
        continuation.finish(throwing: terminalError)
    }
}

private func collect(_ stream: AsyncStream<StreamingSegment>) async -> [StreamingSegment] {
    var segments: [StreamingSegment] = []
    for await segment in stream {
        segments.append(segment)
    }
    return segments
}

// MARK: - Suite

@Suite("task-013 — StreamingTranscriptionUseCase App-side parity")
struct StreamingTranscriptionUseCaseTests {
    // Happy path: each buffer becomes one segment carrying its track and timestamp.
    @Test("happy path yields one segment per buffer with track and timestamp preserved")
    func happyPathYieldsSegmentsInOrder() async throws {
        let engine = ScriptedTranscriptionEngine(script: [.text("first"), .text("second")])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [
            makeBuffer(timestamp: 0, track: .microphone),
            makeBuffer(timestamp: 1, track: .system),
        ])

        let segments = await collect(useCase.transcribeStream(input, modelId: ModelID("m")))

        #expect(segments.count == 2)
        #expect(segments[0].text == "first")
        #expect(segments[0].track == .microphone)
        #expect(segments[0].timestamp == 0)
        #expect(segments[1].text == "second")
        #expect(segments[1].track == .system)
        #expect(segments[1].timestamp == 1)
        #expect(segments.allSatisfy { !$0.isError })
    }

    @Test("empty and whitespace-only segments are filtered out")
    func emptySegmentsAreFiltered() async throws {
        let engine = ScriptedTranscriptionEngine(script: [.text(""), .text("   "), .text("real")])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [
            makeBuffer(timestamp: 0), makeBuffer(timestamp: 1), makeBuffer(timestamp: 2),
        ])

        let segments = await collect(useCase.transcribeStream(input, modelId: ModelID("m")))

        #expect(segments.count == 1)
        #expect(segments.first?.text == "real")
    }

    @Test("consecutive duplicate (text, track) segments are deduplicated")
    func consecutiveDuplicatesAreDropped() async throws {
        let engine = ScriptedTranscriptionEngine(script: [.text("same"), .text("same"), .text("new")])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [
            makeBuffer(timestamp: 0), makeBuffer(timestamp: 1), makeBuffer(timestamp: 2),
        ])

        let segments = await collect(useCase.transcribeStream(input, modelId: ModelID("m")))

        #expect(segments.map(\.text) == ["same", "new"])
    }

    // Resume-after-interruption: a mid-stream transcription failure is
    // transient — the loop surfaces an error segment, then picks up with the
    // next buffer from the last committed segment instead of restarting.
    @Test("resume after interruption: transient failure yields error segment then continues from last committed segment")
    func resumeAfterInterruptionContinuesFromLastCommittedSegment() async throws {
        let engine = ScriptedTranscriptionEngine(script: [.text("one"), .failure, .text("three")])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [
            makeBuffer(timestamp: 0), makeBuffer(timestamp: 1), makeBuffer(timestamp: 2),
        ])

        let segments = await collect(useCase.transcribeStream(input, modelId: ModelID("m")))

        #expect(segments.count == 3, "expected committed, error, resumed segments — got \(segments.map(\.text))")
        #expect(segments[0].text == "one")
        #expect(segments[1].isError, "the interrupted chunk must surface as an error segment")
        #expect(segments[1].isFinal == false, "a transient per-chunk failure must not be terminal")
        #expect(segments[1].errorMessage != nil)
        #expect(segments[2].text == "three", "stream must resume with the next buffer, not restart")
        #expect(segments[2].isError == false)

        // The engine was never re-driven over already-committed buffers.
        #expect(await engine.transcribeCallCount == 3)
        let offsets = await engine.contexts.map(\.timestampOffset)
        #expect(offsets == [0, 1, 2], "resume must continue from the buffer after the interruption")
    }

    // Terminal error: upstream capture failure ends the stream with a single
    // terminal error segment after all committed segments.
    @Test("upstream capture failure yields a terminal error segment and finishes the stream")
    func upstreamFailureIsTerminal() async throws {
        let engine = ScriptedTranscriptionEngine(script: [.text("committed")])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [makeBuffer(timestamp: 0)], terminalError: UpstreamCaptureError())

        let segments = await collect(useCase.transcribeStream(input, modelId: ModelID("m")))

        #expect(segments.count == 2)
        #expect(segments[0].text == "committed")
        #expect(segments[1].isError, "capture failure must surface as an error segment")
        #expect(segments.last?.isError == true, "the error segment must be the last emission before finish")
    }

    @Test("model load failure with engine not ready aborts with a single terminal error segment")
    func modelLoadFailureAbortsStream() async throws {
        let modelId = ModelID("broken")
        let engine = ScriptedTranscriptionEngine(script: [.text("never")], failingModels: [modelId], ready: false)
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [makeBuffer(timestamp: 0)])

        let segments = await collect(useCase.transcribeStream(input, modelId: modelId))

        #expect(segments.count == 1)
        #expect(segments.first?.isError == true)
        #expect(segments.first?.isFinal == true, "a load abort is terminal")
        #expect(await engine.transcribeCallCount == 0, "no buffer may be transcribed after a load abort")
    }

    @Test("model load failure with engine already ready continues streaming")
    func modelLoadFailureWithReadyEngineContinues() async throws {
        let modelId = ModelID("broken")
        let engine = ScriptedTranscriptionEngine(script: [.text("still works")], failingModels: [modelId], ready: true)
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [makeBuffer(timestamp: 0)])

        let segments = await collect(useCase.transcribeStream(input, modelId: modelId))

        #expect(segments.count == 1)
        #expect(segments.first?.text == "still works")
        #expect(segments.first?.isError == false)
    }

    // Fallback overload: preferred model load failure falls back and streams
    // with the fallback model id in every transcription context.
    @Test("fallback overload uses fallback model when preferred load fails")
    func fallbackOverloadFallsBack() async throws {
        let preferred = ModelID("preferred")
        let fallback = ModelID("fallback")
        let engine = ScriptedTranscriptionEngine(script: [.text("via fallback")], failingModels: [preferred])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [makeBuffer(timestamp: 0)])

        let segments = await collect(useCase.transcribeStream(input, preferredModelId: preferred, fallbackModelId: fallback))

        #expect(segments.count == 1)
        #expect(segments.first?.text == "via fallback")
        #expect(await engine.loadedModels == [fallback])
        #expect(await engine.contexts.first?.modelId == fallback)
    }

    @Test("fallback overload resume after interruption matches primary overload semantics")
    func fallbackOverloadResumesAfterInterruption() async throws {
        let engine = ScriptedTranscriptionEngine(script: [.text("one"), .failure, .text("three")])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [
            makeBuffer(timestamp: 0), makeBuffer(timestamp: 1), makeBuffer(timestamp: 2),
        ])

        let segments = await collect(useCase.transcribeStream(
            input,
            preferredModelId: ModelID("m"),
            fallbackModelId: ModelID("f")
        ))

        #expect(segments.map(\.isError) == [false, true, false])
        #expect(segments[0].text == "one")
        #expect(segments[2].text == "three")
    }

    @Test("fallback overload aborts with terminal error when both model loads fail")
    func fallbackOverloadAbortsWhenBothLoadsFail() async throws {
        let preferred = ModelID("preferred")
        let fallback = ModelID("fallback")
        let engine = ScriptedTranscriptionEngine(script: [.text("never")], failingModels: [preferred, fallback])
        let useCase = StreamingTranscriptionUseCase(transcription: engine)

        let input = makeInputStream(buffers: [makeBuffer(timestamp: 0)])

        let segments = await collect(useCase.transcribeStream(input, preferredModelId: preferred, fallbackModelId: fallback))

        #expect(segments.count == 1)
        #expect(segments.first?.isError == true)
        #expect(segments.first?.isFinal == true)
        #expect(await engine.transcribeCallCount == 0)
    }
}

import Domain
import Foundation
import OSLog

/// Orchestrates a post-transcription diarization pass.
///
/// Loads stored audio for a recording, runs it through the diarization engine
/// to identify speaker boundaries, then merges those boundaries with the
/// transcription segments to produce a fully attributed ``DiarizedTranscript``.
///
/// Each ``TranscriptionSegment`` is assigned the speaker whose time range has
/// the maximum overlap with it. Segments that fall entirely outside all speaker
/// ranges are labelled `"Unknown"`.
///
/// All I/O is delegated to injected domain protocols — this actor contains no
/// direct file-system, audio-framework, or inference dependencies.
public actor DiarizeMeetingUseCase {
    // MARK: - Dependencies

    private let diarization: any DiarizationEngine
    private let sampleLoader: any AudioSampleLoader
    private let reader: any RecordingReadRepository
    private let writer: any DiarizationWriteRepository

    // MARK: - Type note
    //
    // `reader` and `writer` are separate narrow-capability protocols
    // (task-007): reads go through `RecordingReadRepository` to fetch the
    // stored recording, writes go through `DiarizationWriteRepository` to
    // persist the merged diarization result.

    // MARK: - Logging

    private let logger = Logger(subsystem: "app.the-record", category: "Diarization")

    // MARK: - Init

    public init(
        diarization: any DiarizationEngine,
        sampleLoader: any AudioSampleLoader,
        reader: any RecordingReadRepository,
        writer: any DiarizationWriteRepository
    ) {
        self.diarization = diarization
        self.sampleLoader = sampleLoader
        self.reader = reader
        self.writer = writer
    }

    // MARK: - Diarize

    /// Produces a diarized transcript by aligning speaker segments with
    /// transcription segments for a stored recording.
    ///
    /// - Parameters:
    ///   - recordingId: Unique identifier of the stored recording.
    ///   - transcription: The transcription result to enrich with speaker labels.
    /// - Returns: A ``DiarizedTranscript`` where every segment carries a speaker
    ///   identity, or `"Unknown"` when no speaker segment overlaps it.
    /// - Throws: Any error produced by storage, sample loader, or diarization —
    ///   errors are never swallowed here.
    // swiftlint:disable:next function_body_length
    public func diarize(
        recordingId: RecordingID,
        transcription: TranscriptionResult
    ) async throws -> DiarizedTranscript {
        logger.info("Starting diarization for recording \(recordingId, privacy: .private)")

        // Step 1: Retrieve the stored recording.
        let recording = try await reader.getRecording(id: recordingId)
        let audioURL = recording.metadata.audioURL
        logger.info("Retrieved recording: \(recording.metadata.id, privacy: .private)")

        // Step 2: Load PCM samples.
        let samples = try await sampleLoader.loadSamples(from: audioURL)
        logger
            .info(
                // swiftlint:disable:next line_length
                "Loaded \(samples.count, privacy: .public) samples from \(audioURL.lastPathComponent, privacy: .public)"
            )

        // Step 3: Gate — prepare the engine if it is not yet ready.
        let ready = await diarization.isReady()
        if !ready {
            try await diarization.prepare()
        }

        // Step 3 (continued): Run diarization.
        let startTime = CFAbsoluteTimeGetCurrent()
        let speakerSegments = try await diarization.diarize(samples: samples, sampleRate: 16000)
        logger.info("Diarization engine returned \(speakerSegments.count, privacy: .public) speaker segments")
        for (i, seg) in speakerSegments.prefix(10).enumerated() {
            logger
                .info(
                    // swiftlint:disable:next line_length
                    "  speaker[\(i, privacy: .public)]: id=\(seg.speakerId, privacy: .public) start=\(seg.startTime, format: .fixed(precision: 1), privacy: .public)s end=\(seg.endTime, format: .fixed(precision: 1), privacy: .public)s"
                )
        }

        // Step 4: Merge speaker segments with transcription segments by max overlap.
        logger
            .info(
                // swiftlint:disable:next line_length
                "Merging \(speakerSegments.count, privacy: .public) speaker segments × \(transcription.segments.count, privacy: .public) transcription segments"
            )
        for (i, seg) in transcription.segments.prefix(5).enumerated() {
            logger
                .info(
                    // swiftlint:disable:next line_length
                    "  transcript[\(i, privacy: .public)]: start=\(seg.startTime, format: .fixed(precision: 1), privacy: .public)s end=\(seg.endTime, format: .fixed(precision: 1), privacy: .public)s text=\(String(seg.text.prefix(40)), privacy: .private)"
                )
        }
        // Compute each overlap once per (speaker, transcript) pair — previous code called
        // overlapDuration 3× per transcript segment (2× in max(by:) + 1× to check > 0).
        let diarizedSegments: [DiarizedSegment] = transcription.segments.map { seg in
            let best = speakerSegments
                .map { (speaker: $0, overlap: overlapDuration($0, seg)) }
                .max(by: { $0.overlap < $1.overlap })
            let speakerId: SpeakerID = if let b = best, b.overlap > 0 {
                b.speaker.speakerId
            } else {
                SpeakerID.unknown
            }
            return DiarizedSegment(
                text: seg.text,
                speakerId: speakerId,
                startTime: seg.startTime,
                endTime: seg.endTime,
                confidence: seg.confidence
            )
        }

        let elapsed = CFAbsoluteTimeGetCurrent() - startTime

        // Step 5: Unique speaker count from diarization output.
        let uniqueSpeakers = Set(speakerSegments.map(\.speakerId))
        let count = diarizedSegments.count
        let speakerCount = uniqueSpeakers.count
        logger
            .info(
                // swiftlint:disable:next line_length
                "Merged \(count, privacy: .public) segments across \(speakerCount, privacy: .public) speakers in \(elapsed, format: .fixed(precision: 3), privacy: .public)s"
            )

        let diarizedTranscript = DiarizedTranscript(
            segments: diarizedSegments,
            speakerCount: uniqueSpeakers.count,
            processingTime: elapsed
        )

        // Step 6: Persist the diarization result so speaker labels survive app restart.
        try await writer.attachDiarization(id: recordingId, diarization: diarizedTranscript)
        logger.info("Diarization persisted for recording \(recordingId, privacy: .private)")

        return diarizedTranscript
    }

    // MARK: - Helpers

    private nonisolated func overlapDuration(
        _ speaker: SpeakerSegment,
        _ transcript: TranscriptionSegment
    ) -> TimeInterval {
        max(0, min(speaker.endTime, transcript.endTime) - max(speaker.startTime, transcript.startTime))
    }
}

import Foundation
@testable import Business
import Domain
import Testing

// MARK: - Fakes

/// Read repository returning a fixed stored recording, or throwing when
/// configured with an error.
private actor FakeDiarizationReadRepository: RecordingReadRepository {
    private let stored: StoredRecording?
    private let error: Error?

    init(stored: StoredRecording? = nil, error: Error? = nil) {
        self.stored = stored
        self.error = error
    }

    func getRecording(id: RecordingID) async throws -> StoredRecording {
        if let error { throw error }
        guard let stored else { throw StorageError.recordingNotFound(id: id) }
        return stored
    }

    func listRecordings(limit _: Int?, offset _: Int?) async throws -> [RecordingSummary] { [] }
    func totalStorageSize() async throws -> Int64 { 0 }
    func listPendingSessions() async throws -> [RecordingID] { [] }
    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] { [] }
    func listNeedsRetranscription() async throws -> [RecordingID] { [] }
}

private actor FakeDiarizationWriter: DiarizationWriteRepository {
    private(set) var attachDiarizationCalled = false
    private(set) var lastAttached: DiarizedTranscript?

    func attachDiarization(id _: RecordingID, diarization: DiarizedTranscript) async throws {
        attachDiarizationCalled = true
        lastAttached = diarization
    }
}

/// Spy engine modelling the "not ready but prepare() succeeds" state that a
/// simple stub cannot express — mirrors the App-side BM-038 spy.
private actor SpyDiarizationEngine: DiarizationEngine {
    private var ready: Bool
    private let prepareError: Error?
    private let segments: [SpeakerSegment]
    private let diarizeError: Error?

    private(set) var prepareCalled = false
    private(set) var diarizeCalled = false

    init(
        ready: Bool = true,
        prepareError: Error? = nil,
        segments: [SpeakerSegment] = [],
        diarizeError: Error? = nil
    ) {
        self.ready = ready
        self.prepareError = prepareError
        self.segments = segments
        self.diarizeError = diarizeError
    }

    func isReady() async -> Bool { ready }

    func prepare() async throws {
        prepareCalled = true
        if let prepareError { throw prepareError }
        ready = true
    }

    func diarize(samples _: [Float], sampleRate _: Int) async throws -> [SpeakerSegment] {
        diarizeCalled = true
        if let diarizeError { throw diarizeError }
        return segments
    }
}

private struct StubSampleLoader: AudioSampleLoader {
    func loadSamples(from _: URL) async throws -> [Float] {
        [Float](repeating: 0, count: 16000)
    }
}

// MARK: - Fixtures

private func makeStoredRecording(id: RecordingID = RecordingID("recording-001")) -> StoredRecording {
    StoredRecording(metadata: RecordingMetadata(
        id: id,
        recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
        duration: 120.0,
        fileSize: 2_097_152,
        audioURL: URL(fileURLWithPath: "/recordings/test-audio.wav"),
        transcriptURL: nil,
        modelId: ModelID("openai_whisper-tiny"),
        processingTime: 2.0,
        computeUnit: .cpuOnly,
        wordCount: 0
    ))
}

private func makeSegment(_ id: String, text: String, start: TimeInterval, end: TimeInterval, seq: Int) -> TranscriptionSegment {
    TranscriptionSegment(id: SegmentID(id), text: text, startTime: start, endTime: end, confidence: 0.9, isFinal: true, sequenceNumber: seq)
}

private func makeTranscription(segments: [TranscriptionSegment]) -> TranscriptionResult {
    TranscriptionResult(
        segments: segments,
        fullText: segments.map(\.text).joined(separator: " "),
        processingTime: 1.0,
        modelId: ModelID("openai_whisper-tiny"),
        recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
        computeUnit: .cpuOnly,
        passType: .cleanup
    )
}

/// Three transcript segments across two speaker ranges:
///   seg-0 (0–5 s):   overlap speaker-0 = 5.0, speaker-1 = 0.0 → speaker-0
///   seg-1 (5–10 s):  overlap speaker-0 = 2.0, speaker-1 = 3.0 → speaker-1
///   seg-2 (10–15 s): overlap speaker-0 = 0.0, speaker-1 = 5.0 → speaker-1
private func makeThreeSegmentTranscription() -> TranscriptionResult {
    makeTranscription(segments: [
        makeSegment("seg-0", text: "Hello world", start: 0, end: 5, seq: 0),
        makeSegment("seg-1", text: "How are you", start: 5, end: 10, seq: 1),
        makeSegment("seg-2", text: "I am fine", start: 10, end: 15, seq: 2),
    ])
}

/// speaker-0 covers 0–7 s, speaker-1 covers 7–15 s.
private func makeTwoSpeakerSegments() -> [SpeakerSegment] {
    [
        SpeakerSegment(speakerId: SpeakerID("speaker-0"), startTime: 0, endTime: 7, confidence: 0.9),
        SpeakerSegment(speakerId: SpeakerID("speaker-1"), startTime: 7, endTime: 15, confidence: 0.85),
    ]
}

private func makeUseCase(
    engine: SpyDiarizationEngine,
    reader: FakeDiarizationReadRepository,
    writer: FakeDiarizationWriter = FakeDiarizationWriter()
) -> DiarizeMeetingUseCase {
    DiarizeMeetingUseCase(
        diarization: engine,
        sampleLoader: StubSampleLoader(),
        reader: reader,
        writer: writer
    )
}

// MARK: - Suite (App-side parity, task-012)

@Suite("task-012 — DiarizeMeetingUseCase App-side behavioral parity")
struct DiarizeMeetingUseCaseBehaviorTests {
    @Test("happy path assigns correct speakers to 3 transcript segments across 2 speaker ranges")
    func happyPathAssignsCorrectSpeakers() async throws {
        let engine = SpyDiarizationEngine(segments: makeTwoSpeakerSegments())
        let useCase = makeUseCase(engine: engine, reader: FakeDiarizationReadRepository(stored: makeStoredRecording()))

        let result = try await useCase.diarize(
            recordingId: RecordingID("recording-001"),
            transcription: makeThreeSegmentTranscription()
        )

        #expect(result.segments.count == 3)
        #expect(result.segments[0].speakerId == SpeakerID("speaker-0"))
        #expect(result.segments[1].speakerId == SpeakerID("speaker-1"))
        #expect(result.segments[2].speakerId == SpeakerID("speaker-1"))
        #expect(result.speakerCount == 2)
    }

    @Test("storage failure propagates without being swallowed")
    func storageFailurePropagates() async throws {
        let useCase = makeUseCase(engine: SpyDiarizationEngine(), reader: FakeDiarizationReadRepository())

        await #expect(throws: (any Error).self) {
            _ = try await useCase.diarize(
                recordingId: RecordingID("recording-001"),
                transcription: makeThreeSegmentTranscription()
            )
        }
    }

    @Test("diarization failure propagates without being swallowed")
    func diarizationFailurePropagates() async throws {
        struct EngineError: Error {}
        let engine = SpyDiarizationEngine(diarizeError: EngineError())
        let useCase = makeUseCase(engine: engine, reader: FakeDiarizationReadRepository(stored: makeStoredRecording()))

        await #expect(throws: (any Error).self) {
            _ = try await useCase.diarize(
                recordingId: RecordingID("recording-001"),
                transcription: makeThreeSegmentTranscription()
            )
        }
    }

    @Test("segment outside all speaker ranges is assigned Unknown")
    func segmentWithNoOverlapGetsUnknown() async throws {
        let engine = SpyDiarizationEngine(segments: makeTwoSpeakerSegments())
        let useCase = makeUseCase(engine: engine, reader: FakeDiarizationReadRepository(stored: makeStoredRecording()))

        // seg-gap (20–25 s) has no overlap with the speaker segments (0–15 s).
        let transcription = makeTranscription(segments: [
            makeSegment("seg-0", text: "Hello", start: 0, end: 5, seq: 0),
            makeSegment("seg-gap", text: "Gap segment", start: 20, end: 25, seq: 1),
        ])

        let result = try await useCase.diarize(recordingId: RecordingID("recording-001"), transcription: transcription)

        #expect(result.segments.count == 2)
        #expect(result.segments[0].speakerId == SpeakerID("speaker-0"))
        #expect(result.segments[1].speakerId == SpeakerID.unknown)
    }

    @Test("diarize persists diarization result via writer.attachDiarization")
    func diarizePersistsResultViaWriter() async throws {
        let engine = SpyDiarizationEngine(segments: makeTwoSpeakerSegments())
        let writer = FakeDiarizationWriter()
        let useCase = makeUseCase(engine: engine, reader: FakeDiarizationReadRepository(stored: makeStoredRecording()), writer: writer)

        _ = try await useCase.diarize(
            recordingId: RecordingID("recording-001"),
            transcription: makeThreeSegmentTranscription()
        )

        #expect(await writer.attachDiarizationCalled)
        #expect(await writer.lastAttached?.segments.count == 3)
    }

    @Test("engine not ready, prepare succeeds — lazy-load then diarize fires")
    func engineNotReadyPrepareSucceedsDiarizeRuns() async throws {
        let engine = SpyDiarizationEngine(ready: false, segments: makeTwoSpeakerSegments())
        let useCase = makeUseCase(engine: engine, reader: FakeDiarizationReadRepository(stored: makeStoredRecording()))

        _ = try await useCase.diarize(
            recordingId: RecordingID("recording-001"),
            transcription: makeThreeSegmentTranscription()
        )

        #expect(await engine.prepareCalled, "prepare() must be called when engine is not ready")
        #expect(await engine.diarizeCalled, "diarize() must be called after prepare() succeeds")
    }

    @Test("engine not ready, prepare throws — diarize never fires and error propagates")
    func engineNotReadyPrepareThrowsDiarizeNeverFires() async throws {
        struct PrepareError: Error {}
        let engine = SpyDiarizationEngine(ready: false, prepareError: PrepareError())
        let useCase = makeUseCase(engine: engine, reader: FakeDiarizationReadRepository(stored: makeStoredRecording()))

        await #expect(throws: (any Error).self) {
            _ = try await useCase.diarize(
                recordingId: RecordingID("recording-001"),
                transcription: makeThreeSegmentTranscription()
            )
        }

        #expect(await engine.diarizeCalled == false, "diarize() must NOT be called when prepare() throws")
    }

    @Test("engine already ready — prepare skipped, diarize runs immediately")
    func engineAlreadyReadyPrepareSkipped() async throws {
        let engine = SpyDiarizationEngine(ready: true, segments: makeTwoSpeakerSegments())
        let useCase = makeUseCase(engine: engine, reader: FakeDiarizationReadRepository(stored: makeStoredRecording()))

        _ = try await useCase.diarize(
            recordingId: RecordingID("recording-001"),
            transcription: makeThreeSegmentTranscription()
        )

        #expect(await engine.prepareCalled == false, "prepare() must NOT be called when engine is already ready")
        #expect(await engine.diarizeCalled, "diarize() must run immediately when engine is ready")
    }
}

