    // A target's name line is exactly `name: "<name>",` on its own line —
    // product declarations (`.library(name: ..., targets: ...)`) and
    // `.product(name: ..., package: ...)` dependency entries never are.
    func isTargetNameLine(_ line: String, _ targetName: String? = nil) -> Bool {
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        guard let targetName else { return trimmed.hasPrefix("name: \"") }
        return trimmed == "name: \"\(targetName)\","
    }

    let lines = manifest.components(separatedBy: "\n")
    guard let start = lines.firstIndex(where: { isTargetNameLine($0, name) }) else {
        return ""
    }
    let rest = lines[(start + 1)...]
    let end = rest.firstIndex(where: { isTargetNameLine($0) }) ?? lines.endIndex
    return lines[start..<end].joined(separator: "\n")
}

