import Business
import Domain
import Foundation
import Testing

// MARK: - Root Package.swift location

/// Walks up from this file to the monorepo root and returns the root
/// Package.swift contents. This test file lives at
/// `Record-CrossPlatform-Foundation/Tests/PackageWiring/`, so the repo root is
/// three directories up.
private func rootPackageManifest() throws -> String {
    let thisFile = URL(fileURLWithPath: #filePath)
    let repoRoot = thisFile
        .deletingLastPathComponent() // PackageWiring
        .deletingLastPathComponent() // Tests
        .deletingLastPathComponent() // Record-CrossPlatform-Foundation
        .deletingLastPathComponent() // repo root
    let manifestURL = repoRoot.appendingPathComponent("Package.swift")
    return try String(contentsOf: manifestURL, encoding: .utf8)
}

/// Extracts the target block for `name` from a Package.swift manifest —
/// everything from the `name: "<name>"` line to the next `name:` line (or end).
private func targetBlock(named name: String, in manifest: String) -> String {
    let lines = manifest.components(separatedBy: "\n")
    guard let start = lines.firstIndex(where: { $0.contains("name: \"\(name)\"") }) else {
        return ""
    }
    let rest = lines[(start + 1)...]
    let end = rest.firstIndex(where: { $0.contains("name: \"") }) ?? lines.endIndex
    return lines[start..<end].joined(separator: "\n")
}

// MARK: - Suite (task-015)

@Suite("task-015 — root Package.swift consumes shared CrossPlatform Business")
struct SharedTargetWiringTests {
    // The root Business target must compile the Record-CrossPlatform-Foundation
    // sources (the SSOT), mirroring the existing Alignment-target precedent —
    // not the Record-App fork.
    @Test("root Business target path points at the CrossPlatform Business sources")
    func rootBusinessTargetUsesSharedSources() throws {
        let manifest = try rootPackageManifest()
        let business = targetBlock(named: "Business", in: manifest)

        #expect(!business.isEmpty, "root Package.swift must declare a Business target")
        #expect(
            business.contains("path: \"Record-CrossPlatform-Foundation/Sources/Business\""),
            "Business target must compile the shared CrossPlatform sources"
        )
        #expect(
            !business.contains("path: \"Record-App/Sources/Business\""),
            "Business target must no longer compile the App-side fork"
        )
    }

    // The AlignmentTests block keeps its CrossPlatform test path — the flip
    // must not disturb it beyond product-reference updates.
    @Test("AlignmentTests target block is preserved")
    func alignmentTestsBlockPreserved() throws {
        let manifest = try rootPackageManifest()
        let alignmentTests = targetBlock(named: "AlignmentTests", in: manifest)

        #expect(
            alignmentTests.contains("path: \"Record-CrossPlatform-Foundation/Tests/AlignmentTests\""),
            "AlignmentTests must keep compiling the CrossPlatform test sources"
        )
    }

    // TestMocks must consume the single shared Business copy — with the path
    // flip there is exactly one Business module in the graph, so depending on
    // "Business" is depending on the shared product.
    @Test("TestMocks depends on the single shared Business module")
    func testMocksDependsOnSharedBusiness() throws {
        let manifest = try rootPackageManifest()
        let testMocks = targetBlock(named: "TestMocks", in: manifest)

        #expect(!testMocks.isEmpty, "root Package.swift must declare a TestMocks target")
        #expect(testMocks.contains("\"Business\""), "TestMocks must depend on the shared Business module")

        let business = targetBlock(named: "Business", in: manifest)
        #expect(
            business.contains("Record-CrossPlatform-Foundation"),
            "the Business module TestMocks consumes must be the CrossPlatform copy"
        )
    }

    // Compile-time symbol identity: these references only build if the shared
    // Business/Domain modules export the types the root package consumes.
    @Test("shared Business/Domain modules export the App-consumed symbols")
    func sharedModulesExportConsumedSymbols() {
        let businessSymbol: StartRecordingUseCase.Type = StartRecordingUseCase.self
        let domainSymbol: (any RecordingReadRepository.Type)? = nil

        #expect(businessSymbol == StartRecordingUseCase.self)
        #expect(domainSymbol == nil)
    }
}

