    // Business/Domain modules export the types the root package consumes.
    @Test("shared Business/Domain modules export the App-consumed symbols")
    func sharedModulesExportConsumedSymbols() {
        let businessSymbol: StartRecordingUseCase.Type = StartRecordingUseCase.self
