import Foundation
import Testing

// MARK: - Repo root

/// Walks up from this file to the monorepo root. This test file lives at
/// `Record-CrossPlatform-Foundation/Tests/PackageWiring/`, so the repo root is
/// three directories up.
private func repoRoot() -> URL {
    URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent() // PackageWiring
        .deletingLastPathComponent() // Tests
        .deletingLastPathComponent() // Record-CrossPlatform-Foundation
        .deletingLastPathComponent() // repo root
}

private func appForkExists(_ fileName: String) -> Bool {
    let url = repoRoot()
        .appendingPathComponent("Record-App/Sources/Business/UseCases")
        .appendingPathComponent(fileName)
    return FileManager.default.fileExists(atPath: url.path)
}

// MARK: - Suite (deletion lanes task-016…020)

/// The root Business target compiles the CrossPlatform SSOT (task-015), so
/// each App-side fork file must be deleted — a lingering copy is dead code
/// that silently drifts from the compiled sources.
@Suite("epic-287 deletion lanes — App-side Business fork files are removed")
struct AppForkDeletionTests {
    @Test(
        "task-016: core pipeline use case forks are deleted",
        arguments: [
            "StreamingTranscriptionUseCase.swift",
            "StopAndTranscribeUseCase.swift",
            "StartRecordingUseCase.swift",
            "PipelineCoordinator.swift",
            "DiarizeMeetingUseCase.swift",
        ]
    )
    func corePipelineForksDeleted(fileName: String) {
        #expect(
            !appForkExists(fileName),
            "Record-App/Sources/Business/UseCases/\(fileName) must be deleted — the CrossPlatform copy is the SSOT"
        )
    }
}

