import Foundation
import OSLog
import Domain

/// Manages retention-based cleanup of old recordings.
public actor AutoCleanupUseCase {

    /// The result of a cleanup operation.
    public struct CleanupResult: Sendable {
        /// The number of recordings deleted.
        public let deletedCount: Int
        /// A warning if folder size exceeds the configured threshold.
        public let folderWarning: FolderSizeWarning?

        /// Initializes a cleanup result.
        /// - Parameters:
        ///   - deletedCount: The number of recordings deleted.
        ///   - folderWarning: Optional folder size warning.
        public init(deletedCount: Int, folderWarning: FolderSizeWarning?) {
            self.deletedCount = deletedCount
            self.folderWarning = folderWarning
        }
    }

    private let reader: any RecordingReadRepository
    private let writer: any RecordingWriteRepository
    private let activeSessionProvider: (@Sendable () async -> RecordingID?)?
    private let logger = Logger(subsystem: "app.the-record", category: "AutoCleanup")

    /// Initializes the cleanup use case.
    /// - Parameters:
    ///   - reader: The recording read repository.
    ///   - writer: The recording write repository.
    ///   - activeSessionProvider: Optional provider for the currently active recording ID to protect from deletion.
    public init(
        reader: any RecordingReadRepository,
        writer: any RecordingWriteRepository,
        activeSessionProvider: (@Sendable () async -> RecordingID?)? = nil,
    ) {
        self.reader = reader
        self.writer = writer
        self.activeSessionProvider = activeSessionProvider
    }

    /// Deletes expired recordings based on the policy and optional folder size threshold.
    /// - Parameters:
    ///   - policy: The cleanup policy defining retention and folder size limits.
    ///   - now: The current time used to calculate expiration.
    /// - Returns: Result containing deleted count and optional folder size warning.
    /// - Throws: Storage errors if deletion fails.
    public func cleanup(policy: CleanupPolicy, now: Date) async throws -> CleanupResult {
        let recordings = try await reader.listRecordings()
        logger.info("Starting auto-cleanup.")
        let cutoff = now.addingTimeInterval(-Double(policy.retentionDays) * 86400)
        let activeId = await activeSessionProvider?()

        let expired = recordings.filter { $0.date < cutoff }
        var deletedCount = 0
        var deletedIDs = Set<RecordingID>()

