import Foundation
import Testing

/// Reads .github/workflows/ci.yml from the repo root (three directories up
/// from Record-CrossPlatform-Foundation/Tests/CI/).
private func ciWorkflow() throws -> String {
    let url = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent() // CI
        .deletingLastPathComponent() // Tests
        .deletingLastPathComponent() // Record-CrossPlatform-Foundation
        .deletingLastPathComponent() // repo root
        .appendingPathComponent(".github/workflows/ci.yml")
    return try String(contentsOf: url, encoding: .utf8)
}

/// Returns only the active (non-comment) lines of the workflow.
private func activeLines(_ yaml: String) -> [String] {
    yaml.components(separatedBy: "\n")
        .map { $0.trimmingCharacters(in: .whitespaces) }
        .filter { !$0.isEmpty && !$0.hasPrefix("#") }
}

@Suite("task-021 — ci.yml is restored and runs the unified package graph")
struct WorkflowConfigTests {
    @Test("the on: trigger block is active and fires on push and pull_request")
    func triggerBlockIsActive() throws {
        let lines = activeLines(try ciWorkflow())
        #expect(lines.contains("on:"), "ci.yml must have an uncommented on: block")
        #expect(lines.contains { $0.hasPrefix("push:") }, "ci.yml must trigger on push")
        #expect(lines.contains { $0.hasPrefix("pull_request:") }, "ci.yml must trigger on pull_request")
    }

    @Test("test-macos job builds and tests the root package")
    func macOSJobRunsRootSuite() throws {
        let lines = activeLines(try ciWorkflow())
        #expect(lines.contains { $0.hasPrefix("test-macos:") }, "ci.yml must define an active test-macos job")
        #expect(
            lines.contains { $0.contains("swift build") } && lines.contains { $0.contains("swift test") },
            "test-macos must run swift build and swift test at the root package"
        )
    }

    @Test("test-windows job builds the CrossPlatform package or is dispatch-gated with a #263 pointer")
    func windowsJobBuildsCrossPlatformOrIsGated() throws {
        let yaml = try ciWorkflow()
        let lines = activeLines(yaml)

        let buildsCrossPlatform = lines
            .contains { $0.contains("swift build --package-path Record-CrossPlatform-Foundation") }
            && lines.contains { $0.contains("ProofHarnessWindows") }
        let dispatchGated = lines.contains { $0.hasPrefix("workflow_dispatch") } && yaml.contains("#263")

        #expect(
            buildsCrossPlatform || dispatchGated,
            "test-windows must build the CrossPlatform package + ProofHarnessWindows, or be workflow_dispatch-only with a comment referencing issue #263"
        )
    }
}

